    out=[]
    c=0
    while c<64:
        ch=W.get((wr,c),'.')
        if ch in chars:
            c2=c
            while c2<64 and W.get((wr,c2),'.')==ch: c2+=1
            out.append((ch,c,c2-1)); c=c2
